scripts.squared_digits_map:
def solve(inputs: dict) -> float:
    n = inputs['N']
    k = inputs['K']

    for _ in range(k):
        # Calculate sum of squared digits
        digit_sum = sum(int(d)**2 for d in str(n))
        n = digit_sum

    return float(n)

scripts.collatz:
def solve(inputs: dict) -> float:
    n = inputs['N']
    k = inputs['K']

    for _ in range(k):
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1

    return float(n)

scripts.reverse_and_add:
def solve(inputs: dict) -> float:
    n = inputs['N']
    k = inputs['K']

    for _ in range(k):
        # Reverse the digits and add to original
        reversed_n = int(str(n)[::-1])
        n = n + reversed_n

    return float(n)

scripts.running_total_reset:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    threshold = inputs['T']

    total = 0
    for val in values:
        total += val
        if total > threshold:
            total = 0

    return float(total)

scripts.base_conversion_digit_sum:
def solve(inputs: dict) -> float:
    n = inputs['N']
    base = inputs['BASE']

    # Convert n to the given base and get digits
    if n == 0:
        digits = [0]
    else:
        digits = []
        temp = n
        while temp > 0:
            digits.append(temp % base)
            temp //= base
        digits.reverse()

    # Sum the digits
    digit_sum = sum(digits)

    return float(digit_sum)

